"""Hand-written XIX-A (AIF Distributors) cases and questions. Every figure is checked by the asserts below."""
# multiples
assert 250 / 100 == 2.5 and round((2.5 ** (1 / 5) - 1) * 100, 1) == 20.1
assert (60 / 100, 120 / 100, (60 + 120) / 100) == (.6, 1.2, 1.8)
# tax
assert 10e5 * .125 == 125000
# waterfall: 100 contributed, 160 distributed after 3 years, 8% pref compounded, 100% catch-up, 80:20 after
_pref = 100 * 1.08 ** 3 - 100; _rest = 160 - 100 - _pref; _catch = _pref / .8 * .2; _after = _rest - _catch; _gp = _catch + .2 * _after
assert round(_pref, 2) == 25.97 and round(_catch, 2) == 6.49 and round(_gp, 1) == 12.0 and round(160 - _gp) == 148
# commitment
assert 5 * .4 == 2.0 and 5 - 2.0 == 3.0 and 5e7 * .02 == 1e6
# valuation
_ev = 10 * 50; _eq = _ev - 150; _stake = _eq * .2; _disc = _stake * .8
assert (_ev, _eq, _stake, _disc) == (500, 350, 70, 56)

